<span class="line"><span style="color:#E5C07B;">            self</span><span style="color:#ABB2BF;">.backbone </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> models.</span><span style="color:#61AFEF;">resnet50</span><span style="color:#ABB2BF;">(</span></span>
